def ChkPAN(pan: str) -> bool:
    """VBA mIncmDtls.ChkPAN – PAN 5 letters 4 digits 1 letter"""
    import re
    return bool(re.match(r'^[A-Z]{5}[0-9]{4}[A-Z]$', pan.upper()))

def ChkAadhaar(aadhaar: str) -> bool:
    return bool(re.match(r'^\d{12}$', str(aadhaar)))

def ValidateTAN1_TDS(tan: str) -> bool:
    """SchTDS.ValidateTAN1_TDS"""
    return bool(re.match(r'^[A-Z]{4}[0-9]{5}[A-Z]$', tan.upper()))

def ValidateIncChargeSal(income: float) -> bool:
    return income>=0

def ValidateTotTaxDeducted(tax: float, income: float) -> bool:
    return tax<=income

def CheckIFSC(ifsc: str) -> bool:
    return bool(re.match(r'^[A-Z]{4}0[A-Z0-9]{6}$', ifsc.upper()))

def StateMatchesPin(pincode: str, state: str, pincode_map: dict) -> bool:
    """Sheet1.StateMatchesPin – pincode->state via DataBase CP:CQ 19k"""
    mapped = pincode_map.get(pincode)
    return mapped==state if mapped else True

def GetBankName(ifsc: str, bank_codes: list) -> str:
    """Sheet3.GetBankName – auto fetch bank name from IFSC first 4 chars"""
    code=ifsc[:4]
    for b in bank_codes:
        if b['code']==code:
            return b['name']
    return ""

def compute_hra_exemption_exact(basic, da, hra, rent, is_metro):
    """Schedule EA 10(13A) G12 exact formula"""
    salary=basic+da
    return min(hra, max(0, rent - round(salary*0.1,0)), 0.5*salary if is_metro else 0.4*salary)

def ValidateEA10_13A_1(form_data: dict) -> bool:
    """ModuleEA10_13A.ValidateEA10_13A_1 – 320 lines"""
    # If HRA received, rent paid mandatory
    if form_data.get('hra_received',0)>0 and form_data.get('rent_paid',0)==0:
        return False
    return True

def Validate_80D(form_data: dict) -> List[str]:
    """Sch80D.Validate_80D – 1151 lines"""
    errors=[]
    # Family member check, preventive 5k cap
    if form_data.get('preventive',0)>5000:
        errors.append("Preventive health checkup capped at 5000")
    return errors

def Validate80G_All(form_data: dict) -> List[str]:
    """Sch80G.Validate80G_All – 2411 lines"""
    errors=[]
    for idx, don in enumerate(form_data.get('donations',[])):
        if don.get('amount',0)>0 and not don.get('donee_name'):
            errors.append(f"80G Row {idx+1} donee name mandatory")
    return errors

def Validate_80EE(form_data: dict) -> bool:
    """md80EE.Validate_80EE – 1166 lines, lock_80EE_flag"""
    global lock_80EE_flag
    if form_data.get('80EE',0)>0 and form_data.get('80EEA',0)>0:
        lock_80EE_flag=True
        return False
    return True

def Validate_80EEA(form_data: dict) -> bool:
    """md80EEA.Validate_80EEA – 1311 lines"""
    global lock_80EEA_flag
    if form_data.get('80EE',0)>0 and form_data.get('80EEA',0)>0:
        lock_80EEA_flag=True
        return False
    return True

def ComputeInterest_234B(tax_payable: float, advance: float) -> float:
    """mdCalInterst234B.ComputeInterest + mdTaxCalc.Calculate_InterestPayable234B"""
    if advance >= tax_payable*0.9:
        return 0
    return round((tax_payable-advance)*0.01*12,0)

def Calculate_InterestPayable234A(tax_due, filing_date, due_date):
    from datetime import date
    if isinstance(filing_date,str):
        filing_date=date.fromisoformat(filing_date)
    if isinstance(due_date,str):
        due_date=date.fromisoformat(due_date)
    if filing_date<=due_date:
        return 0
    months=(filing_date.year-due_date.year)*12 + (filing_date.month-due_date.month)
    if filing_date.day>due_date.day:
        months+=1
    return round(tax_due*0.01*months,0)

def Base64_HMACSHA256(message: str, key: str) -> str:
    """mdHashing.Base64_HMACSHA256 + HS256.cls HMACSHA256"""
    import hmac, hashlib, base64
    hm=hmac.new(key.encode(), message.encode(), hashlib.sha256)
    return base64.b64encode(hm.digest()).decode()

